window.DESK_ITEM = {"id": "2026-11-14-44", "issue": "2026-11-14", "date": "2026-11-14", "title": "סופרים כל שבב, ומפספסים את המסלול", "subtitle": "מודל איומים, הגנתי בלבד, למשטר בקרת היצוא של שבבי AI מתקדמים, אחרי שהחשדות סביב Megaspeed הגיעו עד ללשכת המנכ\"ל של Nvidia", "summary": "שבבים אסורים, מתווך בדרום-מזרח אסיה ובכיר שאולי היה מטרה מודיעינית. איפה גבול האמון שאף אחד לא שמר עליו?", "region": "דרום-מזרח אסיה", "country": "סינגפור ומלזיה", "domain": "שרשרת אספקה", "tags": ["בקרת יצוא", "שבבי AI", "איום פנימי", "שרשרת אספקה"], "risk": {"l": 3, "i": 4}, "keyMetric": {"value": "11 איומים", "label": "ב-6 קטגוריות, על 7 רכיבים"}, "facts": [{"k": "המערכת", "v": "בקרת היצוא של שבבי AI: מכירה, שילוח, שימוש, ופיקוח"}, {"k": "גבולות אמון", "v": "4: ארה\"ב, מדינת מעבר, הלקוח, מדינה מוגבלת"}, {"k": "האיום המרכזי", "v": "כוח חישוב אסור מגיע ליעד מוגבל"}, {"k": "מקור", "v": "The Economist, 14 בנובמבר 2026"}], "defensiveNote": "**הגנתי בלבד.** האיומים מתוארים ברמת המושג, כמו במסמך הגנה. אין כאן פרטי ביצוע. טענות שלא הוכחו מסומנות כטענות, וההכחשות כתובות לידן.", "trailer": {"text": "שבב AI מתקדם יוצא מארה\"ב בדרך חוקית. הוא נמכר לחברת ענן בסינגפור, נספר במחסן במלזיה ונרשם ברשומות היבוא. ובכל זאת, פקידים אמריקאים חושדים שכוח החישוב שלו מגיע בדיוק למי שהחוק נועד לעצור. המנכ\"ל של היצרן אומר שספרו כל שבב, ובאותו שבוע מתברר שהקשר שלו עם מנהלת אצל הלקוח נבדק כחשד למאמץ מודיעיני.", "question": "אם כל הספירות נכונות, איפה בדיוק עבר הגבול שאף אחד לא שמר עליו?"}, "minute": ["מאז אוקטובר 2022 ארה\"ב אוסרת למכור לסין את שבבי ה-AI המתקדמים ביותר. לפי הדיווח, חברות סיניות מצאו שתי דרכים לעקוף את האיסור: לשכור כוח חישוב ב[[neocloud|חברות ענן]] מחוץ לסין, או לקבל את השבבים דרך מתווכים בדרום-מזרח אסיה שמבריחים אותם הלאה. במונחי אבטחה, זו [[export-control|בקרת יצוא]] שמנסה לשמור על [[trust-boundary|גבול אמון]] אחד, הגבול של המדינה המוגבלת.", "Megaspeed היא חברת ענן מסינגפור שמשכירה גישה למעבדי AI. היא קיבלה את שמה הנוכחי ב-2023, ותוך זמן קצר הפכה לאחת הקונות הגדולות של Nvidia באזור. פקידים אמריקאים חושדים שהיא פועלת בשני המסלולים, וחוקרים אותה מאז ספטמבר 2024. החברה מכחישה. לפי הערכה של [[short-seller|מוכר בחסר]], חברת הבת שלה במלזיה ייבאה בתוך כ-14 חודשים סחורה בשווי של כ-4.6 מיליארד דולר, ורובה שרתים עם שבבי Nvidia.", "ב-8 בנובמבר הודה ג'נסן הואנג, המנכ\"ל ואחד ממייסדי Nvidia, ברומן מחוץ לנישואים. זה קרה אחרי דיווחים על קשר בינו לבין אליס הואנג (אין קרבה משפחתית), מנהלת ב-Megaspeed שפקידים אמריקאים מאמינים שהיא סוכנת סינית. סין דוחה את הטענה. הדירקטוריון פתח בדיקה אם הוא היה מטרה של מאמץ מודיעיני זר. קודם לכן Nvidia אמרה שהבדיקות שלה לא מצאו הסטה של שבבים, והואנג עצמו אמר שהם ספרו כל שבב של Megaspeed.", "לפי דיווחים ב-Bloomberg וב-New York Times, היועץ המשפטי של Nvidia התערב בשנה שעברה בחקירה של משרד המסחר נגד Megaspeed. Nvidia אומרת שהיא מתייעצת באופן שגרתי עם גורמי הפיקוח כדי לשתף ידע. לפי הדיווח, גם הבית הלבן הוזהר על הקשר לפחות פעמיים. עכשיו הדירקטוריון מתכונן, לפי הדיווח, להדיח את הואנג, והקונגרס זימן אותו לתדרוך סגור. הפרשה עשויה גם להחיות הצעות חוק תקועות, ובהן אחת שתחייב יצואנים להוכיח שהשבבים לא הוסטו, למשל על ידי [[location-verification|אימות המיקום שלהם]]."], "quote": {"text": "counted every one", "who": "ג'נסן הואנג, על השבבים של Megaspeed, כחודש לפני הפרשה", "after": 2}, "claimsNote": "**עובדות וטענות.** החשדות נגד Megaspeed, הטענה שאליס הואנג היא סוכנת והטענה שהמנכ\"ל היה מטרה מודיעינית הם טענות של פקידים ודיווחים. Megaspeed מכחישה, סין דוחה, והבדיקה של הדירקטוריון עדיין לא הסתיימה. המודל כאן לא קובע מי צודק. הוא שואל איך מערכת צריכה להיראות כדי שהשאלה הזאת לא תהיה תלויה באמון באדם אחד.", "bridges": {"dfd": "לפני ששואלים מה השתבש, משרטטים את המערכת: מי משתתף, מה זורם ביניהם, ואיפה עובר הגבול.", "assets": "דיאגרמה לא אומרת מה חשוב. בשביל זה צריך לשאול מה בכלל שווה הגנה, ולמי.", "stride": "עכשיו עוברים על כל רכיב בדיאגרמה עם שש השאלות של STRIDE.", "tree": "אחד-עשר איומים זה הרבה. עץ התקיפה מסדר אותם סביב המטרה של הצד השני.", "risk": "לא כל איום שווה אותו דבר. מדרגים כל אחד לפי סבירות והשפעה.", "mitigations": "דירוג בלי תיקון הוא רק תיעוד. אלה ההגנות, ומה כל אחת מכסה.", "attack": "צוותי אבטחה מדברים בשפה משותפת. כך נראים כמה מהאיומים במונחים של MITRE ATT&CK.", "takeaways": "ומה נשאר מכל זה, מעבר לפרשה עצמה."}, "glossary": {"threat-model": {"term": "מודל איומים", "en": "Threat model", "def": "מסמך שמתאר מערכת, את מה שיכול להשתבש בה ואת ההגנות. עושים אותו לפני השקה או אחרי שינוי גדול, כדי לתקן בעיות כשהן עוד זולות.", "example": "לפני שמשיקים אפליקציית תשלומים, הצוות משרטט את הזרימות ושואל בכל שלב מי יכול לזייף, לשנות או לגנוב."}, "dfd": {"term": "דיאגרמת זרימת נתונים", "en": "Data Flow Diagram (DFD)", "def": "שרטוט עם ארבעה סוגי רכיבים: ישויות חיצוניות (מלבן), תהליכים (צורה מעוגלת), מאגרי נתונים (שני קווים) וזרימות (חיצים). הוא מראה מה עובר בין מי, לא איך כל רכיב בנוי.", "example": "לקוח (ישות) שולח הזמנה (זרימה) לשרת ההזמנות (תהליך), שכותב אותה למסד הנתונים (מאגר)."}, "trust-boundary": {"term": "גבול אמון", "en": "Trust boundary", "def": "קו בדיאגרמה שבו נתונים או שליטה עוברים בין גורמים שאין להם אותה רמת אמון. רוב האיומים נמצאים בדיוק על הקווים האלה, כי שם צריך לבדוק במקום להניח.", "example": "הגבול בין הדפדפן של המשתמש לשרת: כל מה שמגיע מהדפדפן צריך בדיקה, גם אם האתר שלנו שלח אותו."}, "stride": {"term": "STRIDE", "en": "Spoofing, Tampering, Repudiation, Information disclosure, Denial of service, Elevation of privilege", "def": "רשימת בדיקה של שש קטגוריות איומים שפותחה במיקרוסופט: התחזות, שיבוש, הכחשה, חשיפת מידע, מניעת שירות והסלמת הרשאות. שואלים את שש השאלות על כל רכיב בדיאגרמה.", "example": "על טופס התחברות: אפשר להתחזות למשתמש? (S) אפשר לשנות את הבקשה בדרך? (T) המערכת זוכרת מי התחבר? (R)"}, "attack-tree": {"term": "עץ תקיפה", "en": "Attack tree", "def": "תרשים שבראשו המטרה של התוקף, ומתחתיה הדרכים להגיע אליה. צומת \"או\" אומר שמספיקה אחת מהדרכים. צומת \"וגם\" אומר שצריך את כולן. אם חוסמים צעד אחד תחת \"וגם\", כל הענף נחסם.", "example": "כדי לפתוח כספת: לנחש את הקוד או לפרוץ את הדלת. כדי לפרוץ את הדלת: גם כלי וגם זמן בלי שישימו לב."}, "risk-matrix": {"term": "מטריצת סיכון", "en": "Risk matrix", "def": "טבלה שבה ציר אחד הוא הסבירות שהאיום יתממש והציר השני הוא הנזק אם יתממש. המכפלה קובעת סדר עדיפויות. המספרים הם הערכה ולא מדידה, ולכן חשוב לכתוב על מה הם נשענים.", "example": "שרת שעלול ליפול פעם בשנה (סבירות 2) ולהשבית את כל המכירות (השפעה 5) מקבל 10, כלומר עדיפות גבוהה."}, "residual-risk": {"term": "סיכון שיורי", "en": "Residual risk", "def": "הסיכון שנשאר אחרי שכל ההגנות שהוצעו פועלות. אף מערכת לא מגיעה לאפס, ומודל טוב אומר במפורש מה נשאר ומי מקבל את הסיכון הזה.", "example": "גם עם אימות דו-שלבי, משתמש עדיין יכול למסור את הקוד לאדם שמתחזה לנציג. זה סיכון שיורי."}, "export-control": {"term": "בקרת יצוא", "en": "Export control", "def": "חוקים שמגבילים מכירה של טכנולוגיה רגישה ליעדים מסוימים. היצואן צריך לבדוק מי הלקוח ולפעמים לבקש רישיון. האכיפה בארה\"ב נמצאת בעיקר במשרד המסחר.", "example": "מאז 2022 אסור למכור לסין את שבבי ה-AI המתקדמים ביותר בלי רישיון."}, "neocloud": {"term": "ענן GPU (neocloud)", "en": "Neocloud", "def": "חברת ענן חדשה שמתמחה בהשכרת כוח חישוב של מעבדים גרפיים לאימון ולהרצה של מודלי AI. בניגוד לענקיות הענן, הן קטנות, צומחות מהר, ונשענות הרבה על חומרה של יצרן אחד.", "example": "חברה שקונה אלפי שרתים עם שבבי Nvidia ומשכירה אותם לפי שעה לחברות שמאמנות מודלים."}, "diversion": {"term": "הסטה", "en": "Diversion", "def": "מצב שבו סחורה שנמכרה ליעד מותר מגיעה בפועל ליעד אסור, בדרך כלל דרך מתווך. מבחינת הרישומים הכל תקין, ההבדל הוא בין מה שכתוב לבין איפה החומרה נמצאת באמת.", "example": "שרתים שנרשמו כמותקנים במחסן במלזיה ומועברים משם למדינה שלישית."}, "kyc": {"term": "הכרת הלקוח", "en": "Know Your Customer (KYC)", "def": "תהליך שבו ספק בודק מי הלקוח באמת: מי הבעלים, מה הוא עושה, והאם הסיפור שלו הגיוני. בבנקים זו חובה בחוק, ובבקרת יצוא זה חלק מבדיקת המשתמש הסופי.", "example": "בנק שמבקש מחברה חדשה את רשימת בעלי המניות לפני שהוא פותח לה חשבון."}, "end-use": {"term": "בדיקת שימוש סופי", "en": "End-use check", "def": "בדיקה, לפעמים בביקור בשטח, שהסחורה נמצאת אצל מי שהוצהר ומשמשת למה שהוצהר. היא יכולה להיעשות על ידי היצרן או על ידי הרגולטור, וזה משנה הרבה.", "example": "פקח שמגיע למרכז נתונים ומשווה את המספרים הסידוריים של השרתים לרשימה שהוגשה."}, "short-seller": {"term": "מוכר בחסר", "en": "Short seller", "def": "משקיע שמרוויח כשמניה יורדת. חלקם מפרסמים מחקרים על בעיות בחברות. המידע שלהם יכול להיות מדויק, אבל יש להם אינטרס, ולכן מתייחסים אליו כהערכה ולא כעובדה.", "example": "המספר 4.6 מיליארד דולר בפריט הזה הוא הערכה של Culper Research, שהיא חברה כזאת."}, "location-verification": {"term": "אימות מיקום", "en": "Location verification", "def": "רעיון שבו השבב עצמו מוכיח מאיפה הוא פועל, למשל לפי זמן התגובה החתום שלו מול שרתים אמינים. המהירות של אות ברשת מוגבלת, ולכן שבב לא יכול להיראות קרוב יותר ממה שהוא באמת. הוא יכול רק להיראות רחוק יותר.", "example": "אם שבב שאמור להיות בסינגפור עונה לשרת בסינגפור אחרי 80 מילישניות במקום 2, כנראה שהוא לא שם."}, "mitre-attack": {"term": "MITRE ATT&CK", "en": "MITRE ATT&CK", "def": "קטלוג פתוח של טכניקות שתוקפים משתמשים בהן, עם מזהה לכל טכניקה. צוותי הגנה משתמשים בו כשפה משותפת. הוא נבנה לתקיפות סייבר, ולכן מיפוי של מערכת פיזית או אנושית אליו הוא אנלוגיה.", "example": "T1078 היא \"שימוש בחשבונות תקפים\": התוקף נכנס עם שם משתמש וסיסמה אמיתיים במקום לפרוץ."}, "insider": {"term": "איום פנימי", "en": "Insider threat", "def": "סיכון שמגיע ממי שכבר נמצא בתוך גבול האמון: עובד, מנהל או שותף. לא חייבת להיות כוונה רעה. מספיק שמישהו מבחוץ משפיע על אדם עם הרשאות.", "example": "מנהל רכש שחבר קרוב שלו מתמודד במכרז. גם אם הוא הוגן, התהליך כבר לא עצמאי."}, "front-company": {"term": "חברת חזית", "en": "Front company", "def": "חברה שנראית עסק רגיל, אבל משמשת בפועל ערוץ לגורם אחר שלא יכול לפעול בשמו. מבחוץ קשה להבדיל בינה לבין לקוח אמיתי.", "example": "חברה עם משרד קטן, אתר מקצועי ורכש גדול, שהבעלים האמיתיים שלה לא מופיעים בשום מסמך."}, "separation-of-duties": {"term": "הפרדת תפקידים", "en": "Separation of duties", "def": "עיקרון שלפיו אדם אחד לא גם מבצע פעולה רגישה וגם מאשר אותה. המטרה היא שטעות או לחץ על אדם אחד לא יספיקו.", "example": "מי שמזמין ספק חדש במערכת הוא לא מי שמאשר את התשלום הראשון שלו."}}, "dfd": {"title": "מודל המערכת", "intro": "זו [[dfd|דיאגרמת זרימת נתונים]] של משטר בקרת היצוא, מהמכירה ועד השימוש. הקווים האדומים המקווקווים הם [[trust-boundary|גבולות אמון]]. הזרימות המקווקוות הן מה שחשוד, לא מה שהוכח. לחצו על רכיב כדי לראות את האיומים שלו.", "hint": "לחצו על רכיב בדיאגרמה (או עברו אליו במקלדת ולחצו Enter). המספר בעיגול האדום הוא כמה איומים ממופים לרכיב.", "aria": "דיאגרמת זרימת נתונים של בקרת היצוא. הרכיבים הם כפתורים. אותו מידע מופיע ברשימת הזרימות שמתחת.", "boundaries": [{"id": "us", "label": "ארה\"ב · יצרן ורגולטור"}, {"id": "transit", "label": "מדינת מעבר · דרום-מזרח אסיה"}, {"id": "customer", "label": "גבול הלקוח", "inner": true}, {"id": "restricted", "label": "מדינה מוגבלת"}], "nodes": [{"id": "E2", "kind": "entity", "label": "רגולטור יצוא", "sub": "משרד המסחר (BIS)", "zone": "us", "desc": "קובע מה מותר למכור ולמי, מוציא רישיונות וחוקר חשד להפרות. לפי הדיווח, החקירה נגד Megaspeed נפתחה כבר בספטמבר 2024, ועד הפרשה לא הובילה לפעולה גלויה."}, {"id": "P6", "kind": "process", "label": "הנהלה בכירה", "sub": "אצל היצרן", "zone": "us", "desc": "המנכ\"ל וההנהלה. בדיאגרמה הם תהליך ולא רק אנשים, כי הם מקבלים החלטות שמשפיעות על כל השרשרת: ערבות ללקוחות, קשר עם הרגולטור, ומסרים לשוק. זה הרכיב עם הכי הרבה איומים."}, {"id": "P1", "kind": "process", "label": "מכירות ובדיקת לקוח", "sub": "ציות אצל היצרן", "zone": "us", "desc": "מקבל הזמנות, בודק מי הלקוח ומה השימוש המוצהר, ומבקש רישיון כשצריך. כאן נקבע אם לקוח במדינת מעבר נחשב לגיטימי."}, {"id": "P5", "kind": "process", "label": "ביקורת סוף שימוש", "sub": "יצרן ורגולטור", "zone": "us", "desc": "בודק שהחומרה נמצאת איפה שהוצהר. לפי הדיווח, Nvidia אמרה שהבדיקות שלה לא מצאו הסטה. השאלה המקצועית היא מי בודק: היצרן, שמרוויח מהמכירה, או גורם עצמאי."}, {"id": "P3", "kind": "process", "label": "שילוח ומכס", "sub": "דרך יצרני שרתים", "zone": "transit", "desc": "השבבים מגיעים בתוך שרתים שמרכיבים יצרנים אחרים, ונכנסים למדינת המעבר עם הצהרת יבוא. מכאן הם כבר מחוץ לשליטה הישירה של היצרן."}, {"id": "D2", "kind": "store", "label": "רשומות יבוא", "sub": "נתוני סחר", "zone": "transit", "desc": "הצהרות המכס במדינת המעבר. מהן הגיעה ההערכה של כ-4.6 מיליארד דולר ביבוא של חברת הבת במלזיה. זה מקור הזיהוי הכי זמין, והוא לא דורש שיתוף פעולה של אף אחד."}, {"id": "P4", "kind": "process", "label": "ענן GPU", "sub": "neocloud במדינת מעבר", "zone": "customer", "desc": "הלקוח: מפעיל מרכזי נתונים ומשכיר כוח חישוב. כל מה שקורה בתוך הגבול שלו נראה ליצרן רק דרך מה שהלקוח מדווח. פקידים חושדים ש-Megaspeed פעלה כאן בשני המסלולים. החברה מכחישה."}, {"id": "D3", "kind": "store", "label": "מלאי שרתים", "sub": "מספרים סידוריים", "zone": "customer", "desc": "הרשימה של מה מותקן ואיפה. זה המאגר שהמנכ\"ל התכוון אליו כשאמר שספרו כל שבב. רשימה מדויקת מוכיחה שהשבבים נספרו, לא שהם עדיין שם או שמשתמשים בהם כמו שהוצהר."}, {"id": "E3", "kind": "entity", "adversary": true, "label": "קונה חומרה מוסטת", "sub": "השערת חוקרים", "zone": "restricted", "desc": "מי שמקבל שרתים שהוסטו. בדיאגרמה הוא מסומן כיריב משוער. אין בדיווח הוכחה שזה קרה עם Megaspeed."}, {"id": "E4", "kind": "entity", "adversary": true, "label": "שוכרים מרחוק", "sub": "זהות לא ידועה", "zone": "restricted", "desc": "מי שמשתמש בכוח החישוב דרך הרשת בלי שהחומרה זזה. במסלול הזה אין שום הסטה פיזית. השבבים נשארים בדיוק איפה שנספרו."}, {"id": "E5", "kind": "entity", "adversary": true, "label": "גורם מודיעין זר", "sub": "נטען, בבדיקה", "zone": "restricted", "desc": "הדירקטוריון בודק אם המנכ\"ל היה מטרה של מאמץ מודיעיני. סין דוחה את הטענה שאליס הואנג היא סוכנת. בדיאגרמה זה ערוץ השפעה אפשרי, לא עובדה."}], "flows": [{"id": "f1", "from": "P4", "to": "P1", "label": "הזמנה והצהרת שימוש סופי"}, {"id": "f2", "from": "P1", "to": "E2", "label": "בקשת רישיון והחלטה, כשנדרש"}, {"id": "f3", "from": "P1", "to": "P3", "label": "שרתים ומסמכי משלוח"}, {"id": "f4", "from": "P3", "to": "D2", "label": "הצהרת יבוא"}, {"id": "f5", "from": "P3", "to": "P4", "label": "מסירה ללקוח"}, {"id": "f6", "from": "P4", "to": "D3", "label": "רישום מלאי ומספרים סידוריים"}, {"id": "f7", "from": "P5", "to": "D3", "label": "ספירה וביקורת"}, {"id": "f8", "from": "P5", "to": "E2", "label": "דוח ממצאים"}, {"id": "f9", "from": "P4", "to": "E4", "label": "גישה מרחוק לכוח חישוב (מסלול חשוד)", "kind": "threat"}, {"id": "f10", "from": "D3", "to": "E3", "label": "הסטת חומרה (נטען, מוכחש)", "kind": "threat"}, {"id": "f11", "from": "E5", "to": "P6", "label": "ניסיון השפעה (נטען, בבדיקה)", "kind": "influence"}, {"id": "f12", "from": "P6", "to": "P1", "label": "ערבות של ההנהלה ללקוח"}, {"id": "f13", "from": "P6", "to": "E2", "label": "ערוץ ישיר מול הרגולטור", "kind": "influence"}], "layouts": {"wide": {"w": 1000, "h": 560, "nw": 140, "nh": 54, "zones": {"us": {"x": 636, "y": 40, "w": 356, "h": 512, "lx": 980, "ly": 541}, "transit": {"x": 326, "y": 40, "w": 302, "h": 512, "lx": 616, "ly": 541}, "customer": {"x": 342, "y": 302, "w": 270, "h": 222, "lx": 600, "ly": 321}, "restricted": {"x": 8, "y": 40, "w": 310, "h": 512, "lx": 306, "ly": 541}}, "nodes": {"E2": {"x": 720, "y": 95}, "P6": {"x": 910, "y": 95}, "P1": {"x": 910, "y": 230}, "P5": {"x": 720, "y": 380}, "D2": {"x": 477, "y": 95}, "P3": {"x": 477, "y": 230}, "P4": {"x": 477, "y": 375}, "D3": {"x": 477, "y": 475}, "E5": {"x": 163, "y": 95}, "E4": {"x": 163, "y": 330}, "E3": {"x": 163, "y": 475}}, "via": {"f11": [{"x": 163, "y": 20}, {"x": 910, "y": 20}]}, "numAt": {"f11": 0.18}}, "tall": {"w": 400, "h": 910, "nw": 160, "nh": 52, "zones": {"us": {"x": 16, "y": 28, "w": 368, "h": 234, "lx": 24, "ly": 252, "anchor": "end"}, "transit": {"x": 16, "y": 276, "w": 368, "h": 346, "lx": 24, "ly": 296, "anchor": "end"}, "customer": {"x": 200, "y": 382, "w": 178, "h": 226, "lx": 370, "ly": 598}, "restricted": {"x": 16, "y": 636, "w": 368, "h": 266, "lx": 376, "ly": 892}}, "nodes": {"E2": {"x": 105, "y": 72}, "P6": {"x": 295, "y": 72}, "P1": {"x": 295, "y": 188}, "P5": {"x": 105, "y": 188}, "D2": {"x": 105, "y": 336}, "P3": {"x": 295, "y": 336}, "P4": {"x": 295, "y": 444}, "D3": {"x": 295, "y": 548}, "E4": {"x": 105, "y": 704}, "E3": {"x": 295, "y": 704}, "E5": {"x": 105, "y": 824}}, "via": {"f1": [{"x": 388, "y": 444}, {"x": 388, "y": 188}], "f7": [{"x": 8, "y": 188}, {"x": 8, "y": 548}], "f9": [{"x": 105, "y": 444}], "f11": [{"x": 395, "y": 824}, {"x": 395, "y": 72}]}}}}, "assets": {"title": "נכסים: מה שווה הגנה, ולמי", "intro": "מודל איומים מתחיל ממה שמגינים עליו. כאן הנכסים לא כולם טכניים, ולכל אחד יש בעלים אחר. הנקודות מסמנות חשיבות יחסית, לפי ההערכה שלנו.", "items": [{"id": "A1", "name": "יתרון טכנולוגי בחישוב AI", "owner": "ממשל ארה\"ב", "value": 3, "why": "המטרה של כל בקרת היצוא: להאט את היכולת של יריב לאמן מודלים מתקדמים.", "loss": "כוח חישוב מגיע ליעד המוגבל בלי רישיון, והאיסור נשאר רק על הנייר."}, {"id": "A2", "name": "אמינות משטר הפיקוח", "owner": "הרגולטור והקונגרס", "value": 3, "why": "בקרה עובדת גם כהרתעה. אם כולם יודעים שהיא דולפת, היא מפסיקה להרתיע.", "loss": "מסלול עקיפה שמתגלה בפומבי ומלמד אחרים איך עוקפים."}, {"id": "A3", "name": "עצמאות שיקול הדעת של ההנהלה", "owner": "הדירקטוריון", "value": 3, "why": "החלטות על לקוחות וקשרים עם הרגולטור צריכות להתקבל בלי השפעה של קשר אישי.", "loss": "החלטה עסקית שאי אפשר לדעת אם היא נבעה משיקול עסקי או מהשפעה."}, {"id": "A4", "name": "שווי ומוניטין של היצרן", "owner": "בעלי המניות", "value": 2, "why": "לפי הדיווח, המניה ירדה כ-7% אחרי ההודעה של המנכ\"ל ועוד כ-9% במסחר המאוחר, והוגשה תביעה ייצוגית.", "loss": "פגיעה בשווי ובאמון, גם בלי שהוכחה הפרה כלשהי."}, {"id": "A5", "name": "גישה לגיטימית לשבבים באזור", "owner": "לקוחות לגיטימיים בדרום-מזרח אסיה", "value": 2, "why": "רוב הקונים באזור הם עסקים אמיתיים. הם הנכס שהבקרה לא צריכה לפגוע בו.", "loss": "הידוק גורף שחוסם גם אותם, והופך את הבקרה ליקרה מדי פוליטית."}]}, "stride": {"title": "טבלת STRIDE", "intro": "השורות הן רכיבים מהדיאגרמה, והעמודות הן שש הקטגוריות של [[stride|STRIDE]]. לחיצה על משבצת מסננת את הכרטיסים. אותה בחירה עובדת גם מהדיאגרמה למעלה. כל כרטיס כולל בסיס בדיווח, ואת ההגנות שמכסות אותו."}, "threats": [{"id": "S1", "cat": "S", "node": "P1", "title": "חברת חזית מציגה את עצמה כלקוח סופי", "desc": "מתווך במדינת מעבר עובר את בדיקת הלקוח כאילו השרתים נשארים אצלו. מבחוץ [[front-company|חברת חזית]] נראית בדיוק כמו ענן GPU צומח: רכש גדול, הזמנות עקביות, הצהרות מסודרות.", "evidence": "פקידים אמריקאים חושדים ש-Megaspeed מבריחה שבבים לסין, והיא הפכה תוך זמן קצר לאחת הקונות הגדולות באזור.", "l": 4, "i": 5, "res": {"l": 2, "i": 5}, "resNote": "הסבירות יורדת עם בדיקת בעלות אמיתית ואות מיקום. ההשפעה לא משתנה: אם זה קורה, הנזק זהה.", "mits": ["M3", "M1", "M5"], "claim": "טענה, מוכחשת"}, {"id": "S2", "cat": "S", "node": "P4", "title": "זהות השוכרים מרחוק לא ידועה", "desc": "ענן GPU יכול למכור שעות חישוב לכל מי שמשלם. אם אין בדיקה של מי עומד מאחורי החשבון, כל גורם מוגבל יכול להופיע כלקוח רגיל.", "evidence": "לפי הדיווח, חלק מהחברות הסיניות עוקפות את האיסור בשכירת כוח חישוב במרכזי נתונים מחוץ לסין.", "l": 4, "i": 4, "res": {"l": 2, "i": 4}, "resNote": "[[kyc|הכרת לקוח]] לשוכרים מורידה סבירות, אבל לא לאפס: גם חשבון מזוהה יכול לשמש מתווך.", "mits": ["M4"]}, {"id": "T1", "cat": "T", "node": "D3", "title": "רישום מלאי שלא משקף את המציאות", "desc": "הרשימה יכולה להיות נכונה ביום הספירה ולא נכונה למחרת. ספירה שבודקת מסמכים או ביקור מתואם מראש בודקת את הנייר, לא את החומרה.", "evidence": "המנכ\"ל אמר ש-Nvidia ספרה כל שבב של Megaspeed, ו-Nvidia אמרה שהבדיקות שלה לא מצאו הסטה.", "l": 3, "i": 5, "res": {"l": 2, "i": 4}, "resNote": "ביקורת פתע עצמאית ואות מיקום מהשבב הופכים את הספירה מהצהרה למדידה.", "mits": ["M1", "M5"]}, {"id": "T2", "cat": "T", "node": "D2", "title": "הצהרות יבוא כלליות מסתירות מה עבר", "desc": "\"שרתים\" בהצהרת מכס יכולים להיות כל דבר. בלי פירוט וקישור למספרים סידוריים, נתוני הסחר מראים כמות אבל לא לאן היא הולכת אחר כך.", "evidence": "ההערכה של כ-4.6 מיליארד דולר ביבוא נשענת על נתוני סחר, ולפיה רוב הסחורה הייתה שרתים עם שבבי Nvidia.", "l": 3, "i": 3, "res": {"l": 2, "i": 3}, "mits": ["M6"]}, {"id": "T3", "cat": "T", "node": "E2", "title": "השפעה על תהליך הפיקוח עצמו", "desc": "כשלגורם הנבדק יש ערוץ ישיר לגוף שחוקר את הלקוח שלו, אפשר להשפיע על קצב החקירה או על הכיוון שלה, גם בלי כוונה רעה. זה שיבוש של התהליך, לא של הנתונים.", "evidence": "Bloomberg וה-New York Times דיווחו שהיועץ המשפטי של Nvidia התערב בחקירה של משרד המסחר. Nvidia אומרת שהיא מתייעצת עם גורמי הפיקוח באופן שגרתי כדי לשתף ידע.", "l": 3, "i": 4, "res": {"l": 1, "i": 4}, "mits": ["M8"], "claim": "דיווח, עם תגובת Nvidia"}, {"id": "R1", "cat": "R", "node": "P4", "title": "אין דרך להוכיח איפה השרתים היו", "desc": "אם החומרה לא משאירה עקבות של המיקום שלה, הלקוח יכול להכחיש כל טענה, וגם החוקרים לא יכולים להוכיח אותה. ההכחשה עובדת לשני הכיוונים: גם לקוח תמים לא יכול להוכיח שהוא תמים.", "evidence": "החקירה נגד Megaspeed נמשכת מאז ספטמבר 2024, והחברה מכחישה את כל ההאשמות.", "l": 4, "i": 4, "res": {"l": 2, "i": 3}, "resNote": "תיעוד מיקום חתום מאפשר להוכיח, והוא מגן גם על לקוחות לגיטימיים.", "mits": ["M1", "M5"], "claim": "טענה, מוכחשת"}, {"id": "R2", "cat": "R", "node": "P6", "title": "קשרים לא מתועדים בין בכירים ללקוח", "desc": "קשר אישי בין מנהל בכיר לבין מנהלת אצל לקוח, שלא דווח לדירקטוריון, אומר שאי אפשר לשחזר אחר כך אילו החלטות הושפעו ממנו.", "evidence": "לפי הדיווח, השניים צולמו יחד שוב ושוב, והמנכ\"ל תיאר את הקשר כשגרתי כחודש לפני שהודה ברומן.", "l": 3, "i": 4, "res": {"l": 1, "i": 3}, "mits": ["M7"]}, {"id": "I1", "cat": "I", "node": "P6", "title": "בכיר כמטרה של מאמץ מודיעיני", "desc": "בכיר עם גישה לאסטרטגיה, ללוחות זמנים של מוצרים ולשיחות עם הממשל הוא מטרה טבעית. קשר אישי הוא ערוץ שבו מידע יכול לזלוג בלי שאף מערכת תרשום אותו.", "evidence": "הדירקטוריון בודק אם המנכ\"ל היה מטרה של מאמץ מודיעיני זר. סין דוחה את הטענה שאליס הואנג היא סוכנת.", "l": 3, "i": 5, "res": {"l": 2, "i": 4}, "mits": ["M7"], "claim": "טענה, בבדיקה"}, {"id": "D1", "cat": "D", "node": "P5", "title": "עומס על מנגנון האכיפה", "desc": "כשיש הרבה מתווכים, וכל אחד נראה לבד כמו עסק סביר, גוף הפיקוח לא מספיק לבדוק את כולם. זו מניעת שירות של האכיפה: לא משביתים אותה, מציפים אותה.", "evidence": "הדיווח מתאר מתווכים בדרום-מזרח אסיה כמסלול נפוץ, וחקירה אחת שנמשכת יותר משנתיים.", "l": 4, "i": 3, "res": {"l": 3, "i": 3}, "resNote": "ניתוח נתוני סחר עוזר לתעדף, וחובת הוכחה מעבירה חלק מהעבודה ליצואן. העומס לא נעלם.", "mits": ["M6", "M2"]}, {"id": "E1", "cat": "E", "node": "P4", "title": "השכרה מרחוק עוקפת את האיסור", "desc": "האיסור מגדיר את הגבול לפי המקום של החומרה. גישה ברשת חוצה את הגבול בלי שהחומרה זזה, ונותנת ליעד המוגבל את מה שהאיסור נועד למנוע. זו [[export-control|בקרה]] שבודקת את הקופסה ולא את השימוש.", "evidence": "לפי הדיווח, חלק מהחברות הסיניות שוכרות כוח חישוב במרכזי נתונים בחו\"ל, ופקידים חושדים ש-Megaspeed פעלה גם במסלול הזה. החברה מכחישה.", "l": 5, "i": 4, "res": {"l": 3, "i": 4}, "resNote": "זה האיום שנשאר הכי גבוה. הצעות החוק שמוזכרות בדיווח עוסקות בהסטה פיזית, לא בגישה מרחוק.", "mits": ["M4", "M2"], "claim": "טענה, מוכחשת"}, {"id": "E2", "cat": "E", "node": "P6", "title": "אמון יתר בלקוח בגלל קשר אישי", "desc": "כשההנהלה ערבה ללקוח, הלקוח מקבל בפועל הרשאה גבוהה יותר: פחות שאלות, פחות בדיקות, ויותר נכונות להגן עליו מול הרגולטור. זו הסלמת הרשאות שלא עוברת דרך שום מערכת.", "evidence": "לפי הדיווח, Nvidia המשיכה להגן על Megaspeed גם אחרי שהחקירה נפתחה, והמנכ\"ל הצהיר בפומבי שכל השבבים נספרו.", "l": 3, "i": 4, "res": {"l": 1, "i": 4}, "mits": ["M7", "M8"]}], "tree": {"title": "עץ תקיפה לאיום המרכזי", "intro": "בראש ה[[attack-tree|עץ]] נמצאת המטרה של הצד השני: להשתמש בכוח חישוב אסור. הענפים הם הדרכים, ברמת מושג בלבד. צומת \"או\" אומר שמספיקה דרך אחת. צומת \"וגם\" אומר שצריך את כולן.", "howto": "הפעילו הגנות ותראו אילו ענפים נסגרים. האתגר: מה המספר הקטן ביותר של הגנות שסוגר את כל המסלולים?", "root": {"id": "root", "gate": "OR", "label": "**גורם במדינה מוגבלת משתמש בכוח חישוב משבבים אסורים**", "children": [{"id": "A", "short": "הסטה פיזית", "gate": "AND", "label": "**הסטה פיזית** דרך מתווך במדינת מעבר", "children": [{"id": "A1", "gate": "OR", "label": "להיראות לקוח לגיטימי", "children": [{"id": "A1a", "label": "חברת חזית עם בעלות עמומה עוברת בדיקת לקוח", "mits": ["M3"]}, {"id": "A1b", "label": "ערבות של בכיר אצל היצרן מקטינה את הבדיקה", "mits": ["M7"]}]}, {"id": "A2", "gate": "OR", "label": "להעביר את החומרה הלאה בלי שזה יעצור", "children": [{"id": "A2a", "gate": "AND", "label": "לחמוק מכל מנגנון זיהוי", "children": [{"id": "A2a1", "label": "ספירת המלאי לא בודקת את השטח", "mits": ["M5"]}, {"id": "A2a2", "label": "השבב לא מדווח שהוא זז", "mits": ["M1"]}, {"id": "A2a3", "label": "נפח היבוא לא מעורר חשד", "mits": ["M6"]}]}, {"id": "A2b", "label": "החקירה מתעכבת בזכות ערוץ ישיר לרגולטור", "mits": ["M8"]}]}]}, {"id": "B", "short": "השכרה מרחוק", "gate": "AND", "label": "**השכרה מרחוק**, בלי שהחומרה זזה", "children": [{"id": "B1", "label": "ענן במדינת מעבר קונה שבבים כחוק", "legal": "חוקי היום"}, {"id": "B2", "label": "פתיחת חשבון בלי זיהוי של המשתמש בפועל", "mits": ["M4"]}]}]}, "insight": "**מה העץ מגלה.** הענף של ההסטה הפיזית נסגר בכמה דרכים, כי כל מנגנון זיהוי לבד מספיק כדי לעצור אותו. הענף של ההשכרה נסגר רק בהגנה אחת, הכרת השוכרים (M4). הצעות החוק שמוזכרות בדיווח, כולל אימות מיקום, לא נוגעות בו בכלל."}, "riskMatrix": {"title": "מטריצת סיכון", "intro": "כל איום מקבל ציון [[risk-matrix|סבירות והשפעה]] מ-1 עד 5. הציונים הם הערכה שלנו על בסיס הדיווח, לא מדידה. עברו בין \"לפני\" ל\"אחרי\" כדי לראות לאן כל איום זז כשההגנות פועלות.", "note": "השמאלי-תחתון בטוח יותר. הימני-עליון דחוף יותר."}, "mitigations": {"title": "הגנות וסיכון שיורי", "intro": "שמונה הגנות, כל אחת עם סוג, בעלים ומגבלה. שתיים מוזכרות בדיווח כחלק מהצעות חוק. השאר הן הצעה שלנו. סדר העדיפויות נגזר מהמטריצה: קודם מה שמוריד את האיומים הגבוהים.", "items": [{"id": "M1", "type": "detect", "source": "report", "short": "אימות מיקום", "name": "[[location-verification|אימות מיקום]] מהשבב עצמו", "owner": "היצרן, בדרישת הרגולטור", "desc": "השבב מוכיח מדי פעם שהוא קרוב לשרתים אמינים באזור המוצהר, לפי זמן תגובה חתום. אי אפשר לזייף קרבה, רק ריחוק, ולכן שבב שהוסט נחשף.", "limit": "לא עוצר השכרה מרחוק, כי שם השבב באמת נמצא במקום. מעורר שאלות של פרטיות וריבונות אצל הלקוחות."}, {"id": "M2", "type": "prevent", "source": "report", "short": "חובת הוכחה בחוק", "name": "חובה בחוק להוכיח שהשבבים לא הוסטו", "owner": "הקונגרס, דרך הרגולטור", "desc": "מעבירה את נטל ההוכחה מהחוקרים ליצואן. במקום שהרגולטור יצטרך להוכיח הסטה, היצואן צריך להראות שהיא לא קרתה.", "limit": "תלויה במנגנון מדידה כמו M1. בנוסח שמתואר בדיווח היא מכסה הסטה, לא גישה מרחוק."}, {"id": "M3", "type": "prevent", "source": "ours", "short": "בדיקת לקוח מורחבת", "name": "בדיקת לקוח מורחבת", "owner": "מחלקת הציות אצל היצרן", "desc": "בדיקה של הבעלים האמיתיים, של ההיסטוריה של ההנהלה, ושל ההתאמה בין הרכש לבין הקיבולת המוצהרת של מרכז הנתונים. לקוח שצמח פי כמה בשנה אחת מקבל בדיקה עמוקה יותר, לא קלה יותר.", "limit": "חברת חזית מקצועית יכולה לעבור גם בדיקה טובה. זו שכבה, לא חסימה."}, {"id": "M4", "type": "prevent", "source": "ours", "short": "הכרת שוכרים", "name": "[[kyc|הכרת לקוח]] לשוכרי כוח חישוב", "owner": "מפעיל הענן, בדרישת הרגולטור", "desc": "ענן שמשכיר שבבים מבוקרים מחויב לזהות את מי שעומד מאחורי כל חשבון גדול, ולדווח על שימוש שמתאים לאימון מודלים גדולים.", "limit": "קשה לאכוף מחוץ לארה\"ב, ואפשר לעקוף דרך שכבה נוספת של מתווכים."}, {"id": "M5", "type": "detect", "source": "ours", "short": "ביקורת פתע עצמאית", "name": "מרשם מספרים סידוריים וביקורת פתע עצמאית", "owner": "הרגולטור, או גוף בודק מטעמו", "desc": "כל שרת נרשם במספר סידורי עם מיקום. גוף שאינו היצרן מבצע ביקורות פתע, ומשווה את מה שבשטח למרשם. זו [[separation-of-duties|הפרדת תפקידים]]: מי שמוכר הוא לא מי שבודק.", "limit": "יקר, ותלוי בהסכמה של מדינת המעבר לביקורות בשטח שלה."}, {"id": "M6", "type": "detect", "source": "ours", "short": "ניתוח נתוני סחר", "name": "ניתוח נתוני סחר מול קיבולת", "owner": "הרגולטור והמכס", "desc": "השוואה אוטומטית בין נפח היבוא של כל לקוח לבין מה שמרכז הנתונים שלו יכול בכלל להפעיל, לפי חשמל ושטח. פער גדול מסמן מועמד לבדיקה. ראו כלל לדוגמה למטה.", "limit": "מסמן חשד, לא מוכיח. דורש נתוני קיבולת שלא תמיד זמינים."}, {"id": "M7", "type": "prevent", "source": "ours", "short": "ניגוד עניינים", "name": "גילוי ניגוד עניינים ותדריכי מודיעין נגדי", "owner": "הדירקטוריון", "desc": "כל קשר אישי של בכיר עם גורם אצל לקוח, ספק או רגולטור מדווח לוועדה עצמאית. בכירים בחברות עם טכנולוגיה מבוקרת מקבלים תדריך קבוע על ניסיונות השפעה, כמו שמקבלים עובדי ממשל.", "limit": "תלוי בדיווח עצמי. לא עוזר כשמי שאמור לדווח הוא גם מי שמחליט מה מדווחים."}, {"id": "M8", "type": "detect", "source": "ours", "short": "תיעוד מגע עם הרגולטור", "name": "תיעוד כל מגע עם הרגולטור בחקירה פתוחה", "owner": "הייעוץ המשפטי והרגולטור", "desc": "כל פנייה של היצרן לגוף שחוקר את אחד הלקוחות שלו מתועדת ונגישה לוועדת ביקורת. ההתייעצות השגרתית ממשיכה, אבל היא שקופה.", "limit": "לא מונע השפעה דרך ערוצים לא פורמליים, למשל דרך הדרג הפוליטי."}], "rule": {"title": "כלל זיהוי לדוגמה (M6)", "intro": "כך יכול להיראות הכלל שמסמן לקוחות שהיבוא שלהם גדול ממה שהם יכולים להפעיל. זה פסאודו-קוד בסגנון SQL. הספים מופיעים להמחשה בלבד.", "code": "-- Flag importers whose GPU-server imports exceed what their sites can power\nSELECT i.importer_id,\n       SUM(i.declared_value_usd)               AS imports_12m,\n       SUM(i.est_gpu_count)                    AS gpus_12m,\n       c.powered_mw,\n       SUM(i.est_gpu_count) * 1.2 / 1000.0     AS mw_needed   -- ~1.2 kW per GPU incl. overhead (illustrative)\nFROM   trade_imports i\nJOIN   site_capacity c ON c.importer_id = i.importer_id\nWHERE  i.hs_code IN ('847150', '847330')       -- servers and parts\n  AND  i.import_date >= CURRENT_DATE - INTERVAL '12 months'\nGROUP  BY i.importer_id, c.powered_mw\nHAVING SUM(i.est_gpu_count) * 1.2 / 1000.0 > 1.5 * c.powered_mw   -- needs 50% more power than it has\nORDER  BY mw_needed / NULLIF(c.powered_mw, 0) DESC;", "note": "הכלל לא בודק אם יש הסטה. הוא בודק אם החשבון סוגר. זה מה שהופך אותו לשימושי: הוא לא דורש שיתוף פעולה של הלקוח."}, "residual": "גם עם כל שמונה ההגנות, שני דברים נשארים פתוחים. הראשון הוא השכרה מרחוק דרך שכבות של מתווכים (E1), כי הגבול מוגדר לפי מיקום ולא לפי שימוש. השני הוא השפעה אישית על מקבלי החלטות, כי שום מנגנון לא מחליף דירקטוריון ששואל שאלות. את הסיכון הזה מקבלים בפועל הממשל, שקובע את הגדרת האיסור, והדירקטוריון, שקובע כמה עצמאות יש לבקרה הפנימית."}, "attack": {"title": "מיפוי ל-MITRE ATT&CK", "intro": "[[mitre-attack|MITRE ATT&CK]] נבנה לתקיפות סייבר. המערכת כאן היא שרשרת אספקה ותהליך אנושי, ולכן המיפוי הוא אנלוגיה. הוא שימושי כי הוא מראה שאותם דפוסים מוכרים כבר לצוותי הגנה.", "items": [{"id": "T1591.004", "name": "Gather Victim Org Information: Identify Roles", "where": "איתור בעלי תפקידים עם השפעה על החלטות, כמו מנכ\"ל שמחליט על לקוחות ומדבר עם הממשל.", "threats": ["I1"]}, {"id": "T1199", "name": "Trusted Relationship", "where": "ניצול האמון בין יצרן ללקוח קבוע: לקוח שההנהלה ערבה לו נבדק פחות.", "threats": ["E2", "S1"]}, {"id": "T1078", "name": "Valid Accounts", "where": "שימוש בחשבונות תקינים אצל ענן GPU במקום הברחה. אין פריצה, יש לקוח משלם.", "threats": ["E1", "S2"]}, {"id": "T1036", "name": "Masquerading", "where": "פעילות אסורה שמתחפשת לפעילות עסקית רגילה, כמו חברת חזית שנראית ענן צומח.", "threats": ["S1"]}], "caveat": "אין ב-ATT&CK טכניקה להברחה פיזית או להשפעה על רגולטור. הדפוסים האלה נשארים במודל בלי מיפוי, וזה בסדר: המיפוי עוזר לשפה משותפת, הוא לא המטרה."}, "takeaways": [{"kind": "טכנולוגי", "text": "בקרה שנשענת על ספירה ומסמכים בודקת את הנייר. אות מיקום מהשבב עצמו הופך אותה מהצהרה למדידה, ומגן גם על לקוח תמים שרוצה להוכיח שהוא תמים."}, {"kind": "טכנולוגי", "text": "גבול אמון שמוגדר לפי המקום של החומרה מפספס כל מה שעובר ברשת. ההשכרה מרחוק היא הענף היחיד בעץ שההצעות שבדיווח לא סוגרות."}, {"kind": "אנושי", "text": "הרכיב עם הכי הרבה איומים בדיאגרמה הוא לא שרת אלא הנהלה. כשמי שערב ללקוח הוא גם מי שקשור אליו אישית, הפרדת התפקידים נעלמת בלי שאף אחד מחק אותה."}, {"kind": "מקצועי", "text": "מודל איומים טוב כולל גם ערוצי השפעה על הפיקוח עצמו. השאלה \"מי בודק את הבודק\" שייכת לדיאגרמה, לא רק לביקורת שבאה אחרי."}], "docsIntro": "אותו מודל איומים כמסמך עבודה: היקף, נכסים, רכיבים, טבלת איומים, עץ תקיפה, הגנות, סיכון שיורי ונספח מונחים. בעברית ובאנגלית.", "docs": [{"href": "threat-model-he.pdf", "ext": "PDF", "label": "מודל איומים", "lang": "עברית"}, {"href": "threat-model-he.docx", "ext": "DOCX", "label": "מודל איומים", "lang": "עברית, לעריכה"}, {"href": "threat-model-en.pdf", "ext": "PDF", "label": "Threat Model", "lang": "English"}, {"href": "threat-model-en.docx", "ext": "DOCX", "label": "Threat Model", "lang": "English, editable"}], "source": "מבוסס על דיווח ב-The Economist, 14 בנובמבר 2026 (\"CUDA known better\", מדור Business). הדירוגים, ההגנות והמסקנות הם ניתוח לימודי שלנו, לא קביעה עובדתית לגבי אנשים או חברות.", "scope": {"in": ["הדרך של שבב AI מבוקר מהמכירה ועד השימוש: בדיקת לקוח, רישוי, שילוח, מכס, תפעול בענן GPU וביקורת סוף שימוש", "גישה מרחוק לכוח חישוב כמסלול עקיפה", "ערוצי השפעה אנושיים על ההחלטות ועל הפיקוח: הנהלה, ייעוץ משפטי, רגולטור"], "out": ["אבטחה טכנית של השבב עצמו (קושחה, ערוצי צד)", "תקיפות סייבר על הרשתות של היצרן או הלקוח", "השאלה אם מדיניות היצוא נכונה", "חיי הפרט של המעורבים, מעבר לקשר שרלוונטי לתהליך"]}};
